
/**
 * 埃及的幻想
 * 
 */
let minorIdx = [13,18,23,28,33]
let majorIdx = [9,14,19,24,29,34]
let grandIdx = [5,10,15,20,25,30,35]
cc.Class({
    extends: require("LMSlots_Slots_Base"),

    properties: {
       _canShowStop:false,
        _reelNodes:[],
        _moveIdxList:[],
        _spinTimes:[],
        _bonusGameSuccess:null,
        _spinTimesNum:3,
        _jackpotTitleWin:[],
        _jackpotKuangWin:[],
        _prizePool:null,
        _initMoveIdxList:[],
        // _bonusJieSuanGuang:null,
    },

    onLoad(){
        this._super()
        this._prizePool = cc.find("LMSlots_PrizePool_1",this.node.parent).getComponent("LMSlots_PrizePool_Base")
        // this._bonusJieSuanGuang = cc.find("bonusJieSuanGuang",this.node.parent)
    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },

    //初始化
    Init:function(){
        this._topScript = cc.vv.gameData.GetTopScript()
        this._bottomScript = cc.vv.gameData.GetBottomScript()

        this._cfg = cc.vv.gameData.getGameCfg()
        this._col = 5
        this._row = 7

        for (let i = 0; i < this._col; i++) {
            let node = cc.find("reels/reel" + (i+1),this.node)
            this._reelNodes.push(node)

        }
        this.createReels(this._col,this._row)

        this._bottomScript.ShowBtnsByState("idle")

        this.RegisterEvent()

        //断线重连的显示
        this.ReconnectShow()

        for (let i = 0; i < 3; i++) {
            this._spinTimes.push(cc.find("spinTimesBg/text"+(i+1),this.node))
            if(i !== 2){
                this._spinTimes[i].color = this._cfg.grayColor
            }
        }

        for (let i = 2; i < this._reelNodes.length; i++) {
            let title = cc.find("roof/win",this._reelNodes[i])
            this._jackpotTitleWin.push(title)
            let kuang = cc.find("jackpotKuang",this._reelNodes[i])
            this._jackpotKuangWin.push(kuang)
        }

        //初始化奖池
        // this.CheckJoopLock()
    },

    createReels(col,row){
        let reelCmp = "CaoCao_reelbonus"
        this._moveIdxList = []
        for (let i = 0; i < 3; i++) {
            let reel = cc.find("mask/holder/reel"+(i+1),this._reelNodes[0])
            let scp = reel.addComponent(reelCmp)
            scp.Init(20 + (2 - i)*col,1,this._topAniNode)
            this._reels[20 + (2 - i)*col] = scp
            this._moveIdxList.push(21 + (2 - i)*col)
        }
        for (let i = 0; i < 4; i++) {
            let reel = cc.find("mask/holder/reel"+(i+1),this._reelNodes[1])
            let scp = reel.addComponent(reelCmp)
            scp.Init(16 + (3 - i)*col,1,this._topAniNode)
            this._reels[16 + (3 - i)*col] = scp
            this._moveIdxList.push(17 + (3 - i)*col)
        }
        for (let i = 0; i < 5; i++) {
            let reel = cc.find("mask/holder/reel"+(i+1),this._reelNodes[2])
            let scp = reel.addComponent(reelCmp)
            scp.Init(12 + (4 - i)*col,1,this._topAniNode)
            this._reels[12 + (4 - i)*col] = scp
            this._moveIdxList.push(13 + (4 - i)*col)
        }
        for (let i = 0; i < 6; i++) {
            let reel = cc.find("mask/holder/reel"+(i+1),this._reelNodes[3])
            let scp = reel.addComponent(reelCmp)
            scp.Init(8 + (5 - i)*col,1,this._topAniNode)
            this._reels[8 + (5 - i)*col] = scp
            this._moveIdxList.push(9 + (5 - i)*col)
        }
        for (let i = 0; i < 7; i++) {
            let reel = cc.find("mask/holder/reel"+(i+1),this._reelNodes[4])
            let scp = reel.addComponent(reelCmp)
            scp.Init(4 + (6 - i)*col,1,this._topAniNode)
            this._reels[4 + (6 - i)*col] = scp
            this._moveIdxList.push(5 + (6 - i)*col)
        }
        this._initMoveIdxList = Global.copy(this._moveIdxList)
    },

    //重写
    ShowWinTrace:function(){
        this._super()
    },

    //重写
    StartMove:function(){
        cc.vv.gameData.GetBottomScript().ShowBtnsByState("moveing_1")
        this.unschedule(this.StartMove)

        this._bStopRightnow = null
        this._gameInfo = null

        //top状态更新
        this._topScript.StartMove()

        //清理数据
        cc.vv.gameData.ClearOneRoundData()

        //每列转起来
        this.MoveReels(this._reels)

        this.setSpinTime(this._spinTimesNum - 1)

        //设置停止时间
        //就是收到结果后，如果多少秒会开始停止
        this._stopTime = this.GetStopTime()

        this._canShowStop = false
        let req = {c: MsgId.SLOT_SUBGAME_DATA};
        req.uid = Global.playerData.uid;
        req.gameid = cc.vv.gameData._gameId;
        req.data = {};
        req.data.rtype = 3
        cc.vv.NetManager.send(req);
    },

    StopMove:function(){
        this._bStopRightnow = true
        cc.vv.gameData.GetBottomScript().ShowBtnsByState("moveing_1")
        this.unschedule(this.StartMove)

        this._stopTime = -1
        for(let i = 0; i < this._reels.length; i++ ){
            let item = this._reels[i]
            if(item){
                let reelStopInterv = 0 //立即停止
                item.StopMove(reelStopInterv)
                item.StopMoveRightNow()
            }
        }
    },

    MoveReels:function(arry){
        this.moveReelLastIdx = 0
        let sortArray = (a,b)=>{
            let acol = (a - 1) % this._col
            let bcol = (b - 1) % this._col
            if(acol == bcol){
                return a - b
            }else{
                return acol - bcol
            }
        }
        this._moveIdxList.sort(sortArray)
        for (let i = 0; i < this._moveIdxList.length; i++) {
            const idx = this._moveIdxList[i] - 1
            let reel = arry[idx]
            if(reel){
                reel.StartMove()
                this.moveReelLastIdx = idx
            }
        }
    },

    //重写
    //gameData模块收到数据后，转发到此处
    async onMsgSpine(msg){
        this._gameInfo = msg
        this.SetSlotsResult(msg.result.idxs,msg.result.items)
        this._canShowStop = true
    },

    ShowWinCoin(nAddWin,nTotalWin,bUpdateBalance){
        return new Promise(async (sucess, failed)=>{
            this.ShowBottomWin(nAddWin,nTotalWin,bUpdateBalance,sucess)
        });
    },

    //全部列都停止了,重写
    //处理停下后的中奖情况，这里多数情况需要根据自己的逻辑来处理
    async OnSpinEnd(){
        cc.vv.gameData.GetBottomScript().ShowBtnsByState("moveing_1")
        this.setSpinTime(this._gameInfo.bonusGame.spinCnt)
        let jackpotId = this.getJackPotId()
        if(jackpotId){
            this.setJackpotWinEffect(jackpotId)
        }
        if(this._gameInfo.bonusGame.isEnd){  //结束游戏
            await this.ShowResult(this._gameInfo.bonusGame.bonusIdxs,this._gameInfo.bonusGame.bonusItems)
            cc.vv.gameData.getManage().changeNormalSlots()
            await this.ShowWinCoin(this._gameInfo.bonusGame.winCoin,this._gameInfo.bonusGame.winCoin,true)
            this.exitBonusGame()
        }else {
            cc.vv.gameData.GetBottomScript().ShowBtnsByState("bounsGame")
            this.autoSpin()
        }
    },

    //重写
    //备份当前状态
    Backup() {
        this._super()
    },

    //重写
    //恢复到保存的状态
    Resume() {
        this.clearSlots()
        this._super()
    },

    clearSlots(){
        for (const i in this._reels) {
            const reel = this._reels[i];
            if(reel){
                for (let j = 0; j < reel._symbols.length; j++) {
                    const symbol = reel._symbols[j];
                    symbol.setAnimationToTop(false)
                    symbol.ShowKuang(false)
                }
            }
        }
    },

    CanStopSlot(){
        return this._canShowStop
    },

    //切换的时候做动画
    showAnimation(){
        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.music_Puss_Reel_up)
        for (let i = 0; i <this._reelNodes.length; i++) {
            const reel = this._reelNodes[i];
            reel.height = 312
            cc.tween(reel).to(0.2,{height:312+i*104}).start()
        }
    },

    initStartSymbol(dataList){
        this._moveIdxList = Global.copy(this._initMoveIdxList)
        for (let i = 0; i < dataList.length; i++) {
            const data = dataList[i]
            let symbol = this.GetSymbolByIdx(21 + i)
            if(symbol){
                symbol.ShowById(data.id,data.data)
            }
            let symbol1 = this.GetSymbolByIdx(21 + i,1)
            if(symbol1){
                symbol1.ShowById(1001)
            }
        }
        for (const reelsKey in this._reels) {
            if(Number(reelsKey) < 20){
                let symbol = this.GetSymbolByIdx(Number(reelsKey)+1)
                if(symbol){
                    symbol.ShowById(1001)
                }
                let symbol1 = this.GetSymbolByIdx(Number(reelsKey)+1,1)
                if(symbol1){
                    symbol1.ShowById(1001)
                }
            }
        }
        for (let i = 0; i < this._spinTimes.length; i++) {
            this._spinTimes[i].color = this._cfg.grayColor
            if(i === 2){
                this._spinTimes[i].color = this._cfg.normalColor
            }
        }
        this._spinTimesNum = 3
    },

    //根据服务端序号获取本地的symbol
    //因为一格就是一列，所以这里获取的是这一列的第一个symbol
    GetSymbolByIdx:function(idx,row = 0){
        let reel = this._reels[idx - 1]
        if(reel){
            return reel.GetSymbolByRow(row)
        }
        return null
    },

    setSpinTime(times){
        if(this._spinTimesNum === times){
            return
        }
        this._spinTimesNum = times
        if(this._spinTimesNum === 3){
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.music_Puss_Respin_rest)
            let respinLizi = cc.find("spinTimesBg/respinLizi",this.node)
            respinLizi.active = true
            let respinLiziAni = respinLizi.getComponent(cc.Animation)
            respinLiziAni.play("respinLizi")
            respinLiziAni.on("finished",()=>{
                respinLiziAni.off("finished")
                respinLizi.active = false
            })
        }
        for (let i = 0; i < this._spinTimes.length; i++) {
            this._spinTimes[i].color = this._cfg.grayColor
            if(i === (times - 1)){
                this._spinTimes[i].color = this._cfg.normalColor
            }
        }
    },

    removeMoveIdxByVal(idx){
        for (let i = 0; i < this._moveIdxList.length; i++) {
            if(this._moveIdxList[i] === idx){
                this._moveIdxList.splice(i,1)
                break
            }
        }
    },

    enterBonusGame(bonusGame,isReConnect){
        return new Promise(async (success,failed)=>{
            Global.SlotsSoundMgr.playBgm(Global.SlotsSoundMgr.Puss_respinbg)
            cc.vv.gameData.getManage()._isInBonus = true
            this._bonusGameSuccess = success
            for (let i = 0; i < bonusGame.bonusIdxs.length; i++) {
                let idx = bonusGame.bonusIdxs[i]
                this.removeMoveIdxByVal(idx)
                let symbol = this.GetSymbolByIdx(idx)
                if(symbol){
                    symbol.ShowById(3,bonusGame.bonusItems[i])
                }
                let symbol1 = this.GetSymbolByIdx(idx,1)
                if(symbol1){
                    symbol1.ShowById(1001)
                }
            }
            if(isReConnect){
                for (let i = 0; i < this._moveIdxList.length; i++) {
                    let idx = this._moveIdxList[i]
                    let symbol = this.GetSymbolByIdx(idx)
                    if(symbol){
                        symbol.ShowById(1001)
                    }
                    let symbol1 = this.GetSymbolByIdx(idx,1)
                    if(symbol1){
                        symbol1.ShowById(1001)
                    }
                }
            }
            this.setSpinTime(bonusGame.spinCnt)
            let data = []
            for (let i = 0; i < bonusGame.jackpotValues.length; i++) {
                const element = bonusGame.jackpotValues[i];
                data.push({prizeType:i,pauseNum:element})
            }
            this._prizePool.PausePool(data)
            let jackpotId = this.getJackPotId()
            if(jackpotId){
                this.setJackpotWinEffect(jackpotId)
            }
            this.autoSpin()
            cc.vv.gameData.GetBottomScript().ShowBtnsByState("bounsGame")
        })
    },

    autoSpin(){
        this.unschedule(this.StartMove)
        this.scheduleOnce(this.StartMove,this._cfg.autoModelDelay)
    },

    exitBonusGame(){
        cc.vv.gameData.getManage()._isInBonus = false
        this.hideJackpotWinEffect()
        this.clearSlots()
        this._prizePool.ResumePausePool()
        if(this._bonusGameSuccess){
            this._bonusGameSuccess()
            this._bonusGameSuccess = null
        }
        Global.SlotsSoundMgr.playNormalBgm(true)
    },

    //处理结果给reel设置结果
    SetSlotsResult:function(bonusIdxs,bonusItems){
        for (let i = 0; i < this._moveIdxList.length; i++) {
            let idx = this._moveIdxList[i]
            this._reels[idx - 1].SetResult([{sid:1001}])
        }
        for (let i = 0; i < bonusIdxs.length; i++) {
            let idx = bonusIdxs[i]
            this._reels[idx - 1].SetResult([{sid:3,data:bonusItems[i]}])
            this.removeMoveIdxByVal(idx)
        }
    },

    ShowResult(bonusIdxs,bonusItems){
        return new Promise(async (success,failed)=>{
            let result = []
            for (let i = 0; i < bonusIdxs.length; i++) {
                result.push({idx:bonusIdxs[i],data:bonusItems[i]})
            }
            let sortArray = (a,b)=>{
                let acol = (a.idx - 1) % this._col
                let bcol = (b.idx - 1) % this._col
                if(acol == bcol){
                    return a.idx - b.idx
                }else{
                    return acol - bcol
                }
            }
            result.sort(sortArray)
            this._coin = 0
            await this.awaitTime(1)
            for (let i = 0; i < result.length; i++) {
                const ret = result[i]
                //珍珠做表现
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.music_Puss_Bonus_EndWin)
                let reel = this._reels[ret.idx - 1]
                if(reel){
                    reel._symbols[0].playTriggerAnimation()
                }
                await this.awaitTime(0.3)
                // this._bonusJieSuanGuang.active = true
                // let bonusJieSuanGuangAni = this._bonusJieSuanGuang.getComponent(cc.Animation)
                // bonusJieSuanGuangAni.play("bonusJieSuanGuang")
                // bonusJieSuanGuangAni.on("finished",()=>{
                //     bonusJieSuanGuangAni.off("finished")
                //     this._bonusJieSuanGuang.active = false
                // })
                this._coin += ret.data.coin
                this._bottomScript.SetWin(this._coin)
                await this.awaitTime(0.2)
            }
            if(this._gameInfo.bonusGame.jackpot){
                await cc.vv.gameData.getPopWinManage().showJackpotWinCoin(this._gameInfo.bonusGame.jackpot.value,this._gameInfo.bonusGame.jackpot.id)
                this._coin += this._gameInfo.bonusGame.jackpot.value
                this._bottomScript.SetWin(this._coin)
            }
            await cc.vv.gameData.getPopWinManage().showBonusGameWinCoin(this._gameInfo.bonusGame.winCoin)
            cc.vv.gameData.AddCoin(this._gameInfo.bonusGame.winCoin)
            success()
        })
    },

    update (dt) {
        if(this._stopTime > 0){
            this._stopTime = this._stopTime - dt
            if(this._stopTime <= 0 ){ //空转时间到了
                if(this.CanStopSlot()){//满足开始停止的条件
                    this._bottomScript.ShowBtnsByState("moveing_2")
                    //倒计时完，设置一次
                    for (const i in this._reels) {
                        let item = this._reels[i]
                        let col = i % this._col
                        let reelStopInterv = this.GetReelStopInter(col)
                        item.StopMove(reelStopInterv)
                    }
                }
                else{
                    //如果没有结果,则延迟一帧
                    this._stopTime = dt

                    //记录一个超时时间.
                    this._roundSpineTime = this._roundSpineTime || 0
                    this._roundSpineTime += dt
                    if(this._roundSpineTime > 30 ){
                        // this._stopTime = -1
                        this._topScript.SetBackLobby(true)
                    }
                }

            }
        }
    },

    setJackpotWinEffect(type){
        if(type < 2 || type > 4){
            return
        }
        this.hideJackpotWinEffect()
        this._jackpotKuangWin[type - 2].active = true
        this._jackpotTitleWin[type - 2].active = true
    },

    hideJackpotWinEffect(){
        for (let i = 0; i < this._jackpotKuangWin.length; i++) {
            this._jackpotKuangWin[i].active = false
        }
        for (let i = 0; i < this._jackpotTitleWin.length; i++) {
            this._jackpotTitleWin[i].active = false
        }
    },

    getJackPotId(){
        let minor = true
        let major = true
        let grand = true
        for (let i = 0; i < this._moveIdxList.length; i++) {
            if(minorIdx.includes(this._moveIdxList[i])){
                minor = false
                break
            }
        }
        for (let i = 0; i < this._moveIdxList.length; i++) {
            if(majorIdx.includes(this._moveIdxList[i])){
                major = false
                break
            }
        }
        for (let i = 0; i < this._moveIdxList.length; i++) {
            if(grandIdx.includes(this._moveIdxList[i])){
                grand = false
                break
            }
        }
        if(grand){
            return 4
        }
        if(major){
            return 3
        }
        if(minor){
            return 2
        }
        return 0
    },
});
