cc.Class({
    extends: require("LMSlots_Logic_Base"),

    properties: {

    },

    InitCommComponent:function(){
        this._super()

        let safeNode = cc.find('Canvas/safe_node')
        let popWinManage = safeNode.getComponentInChildren("CaoCao_Pop")
        if(popWinManage){
            cc.vv.gameData.setPopWinManage(popWinManage)
        }
        let mapControl = safeNode.getComponentInChildren("CaoCao_mapControl")
        if(mapControl){
            cc.vv.gameData.setMapControl(mapControl)
        }
        let manage = safeNode.addComponent("CaoCao_manage")
        if(manage){
            cc.vv.gameData.setManage(manage)
        }
        let free_slots = cc.find('slotsfree',safeNode)
        cc.vv.gameData.SetFreeSlotsScript(free_slots.addComponent("CaoCao_Slotsfree"))
        let bonus_slots = cc.find('slotsbonus',safeNode)
        cc.vv.gameData.SetBonusSlotsScript(bonus_slots.addComponent("CaoCao_Slotsbonus"))
        cc.vv.gameData.SetCollectNode(cc.find("slots/collectNode",safeNode).getComponent("CaoCao_collectNode"))
    },

    //开始游戏
    StartSlot:function(){
        this._super()
        let script_slotsfree = cc.vv.gameData.GetFreeSlotsScript()
        script_slotsfree.Init()
        let script_slotsbonus = cc.vv.gameData.GetBonusSlotsScript()
        script_slotsbonus.Init()
    },

    // LIFE-CYCLE CALLBACKS:

    // update (dt) {},
});
