cc.Class({
    extends: require("CaoCao_symbol"),

    properties: {
        
    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    ShowRandomSymbol:function(){
        let cfg = cc.vv.gameData.getGameCfg()
        let randIdx = Global.random(1,cfg.randomSymbols.length)
        let randVal = cfg.randomSymbols[randIdx-1]
        this.ShowById(randVal)
    },

    //停止最低点之后
    StopMoveDeep(){
        if(this._id === 3){
            this.playStopAnimation(true)
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.music_Puss_Bonus_Down)
        }
    },

    // update (dt) {},
});
