    //播放win效果但又没有spin动画。自己写一个tween的action
    //先填写个默认的。
    playWinTweenAction(){
        let nodeAnimation = this.node.getComponent(cc.Animation)
        nodeAnimation.play("smallSymbolWin")
    },
    //停止tween类型的action动画
    stopWinTweenAction(){
        let nodeAnimation = this.node.getComponent(cc.Animation)
        nodeAnimation.play("smallSymbolIdel")
    },

    OnSymbolAction(symbol){
        let cfg = cc.vv.gameData.getGameCfg()
        let distance = cfg.bounceInfo ? cfg.bounceInfo.distance : 30
        let time = cfg.bounceInfo ? cfg.bounceInfo.time : 0.3

        cc.tween(symbol)
            .to(time,{position:cc.v2(symbol.x,symbol.y + distance)})
            .start()
    },

