    setSymbolCoin(coin){
        // let s13 = cc.find("s13",node)
        let coinNum = cc.find("coinNum",this.node)
        if(coin){
            coinNum.active = true
            coinNum.getComponent(cc.Label).string = Global.convertNumToShort(coin,1000,1)
        } else {
            coinNum.active = false
        }
    },

    ShowById:function(id,data){
        this._id = id
        this._data = data
        this._state = "normal";

        if(this._showNode){
            this._showNode.active = false
        }
        if(this._data){
            this.setSymbolCoin(this._data.coin)
        } else {
            this.setSymbolCoin();
        }
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].node){
            this._showNode = cc.find(cfg.symbol[id].node,this.node)
            this._showNode.active = true
        }
        else{
            console.log("未找到配置id:" + id)
        }
    },

    ShowRandomSymbol:function(){
        let randVal
        let randomcfg = this.GetRandomCfg()
        if(randomcfg){
            let reelrandomCfg = randomcfg[this._reelIdx+1]
            if(reelrandomCfg){
                //gamedata中记录了当前列随机到符号表的序号了，只需要一个个往下随机战士就好
                let randIdx = cc.vv.gameData.GetReelRandomIdx(this._reelIdx)
                if(randIdx){
                    //如果没有就随机一个开始值，如果每次都从0开始，就每次进去游戏都是那几个图标
                    randIdx = Global.random(1,reelrandomCfg.length)-1
                }
                randVal = reelrandomCfg[randIdx]
                if(!randVal){ //如果取到最后了就从头开始取
                    randIdx = 0
                    randVal = reelrandomCfg[randIdx]
                }

                cc.vv.gameData.SetReelRandomIdx(this._reelIdx,++randIdx)
            }
        }
        else{//兼容旧的配置数据
            let cfg = cc.vv.gameData.getGameCfg()
            let randIdx = Global.random(1,cfg.randomSymbols.length)
            randVal = cfg.randomSymbols[randIdx-1]
        }
        let data = null
        if(randVal === 3){
            let betCoin = cc.vv.gameData.GetTotalBet()
            let coin = coinMult[Global.random(0,coinMult.length - 1)]
            data = {coin:coin * betCoin}
        }
        this.ShowById(randVal,data)
        return randVal
    },

    /**
     * 获取随机的符号表，可重写次函数根据需要配置免费游戏的符号表
     *
     */
    GetRandomCfg:function(){
        let cfg = cc.vv.gameData.getGameCfg()
        if(cc.vv.gameData.getMapControl().getIsMapFree()){
            return cfg.cardmapfree2
        }
        let isFree = cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() !== cc.vv.gameData.GetFreeTime()
        if(isFree > 0 && cfg.cardmapfree) {
            return cfg.cardmapfree
        }
        return cfg.cardmap
    },

    //显示随机符号
    ShowInitFreeSymbol:function(){
        let randVal
        let cfg = cc.vv.gameData.getGameCfg()
        let randomcfg = cfg.cardmapfree || cfg.cardmap
        if(randomcfg){
            let reelrandomCfg = randomcfg[this._reelIdx+1]
            if(reelrandomCfg){
                //gamedata中记录了当前列随机到符号表的序号了，只需要一个个往下随机就好
                let randIdx = cc.vv.gameData.GetReelRandomIdx(this._reelIdx)
                if(!cc.js.isNumber(randIdx)){
                    //如果没有就随机一个开始值，如果每次都从0开始，就每次进去游戏都是那几个图标
                    randIdx = Global.random(1,reelrandomCfg.length)-1
                }
                randVal = reelrandomCfg[randIdx]
                if(!randVal){ //如果取到最后了就从头开始取
                    randIdx = 0
                    randVal = reelrandomCfg[randIdx]
                }

                cc.vv.gameData.SetReelRandomIdx(this._reelIdx,++randIdx)
            }
        }
        else{//兼容旧的配置数据
            let cfg = cc.vv.gameData.getGameCfg()
            let randIdx = Global.random(1,cfg.randomSymbols.length)
            randVal = cfg.randomSymbols[randIdx-1]
        }
        this.ShowById(randVal)
    },
