cc.Class({
    extends: cc.Component,

    properties: {
        _pointList:[],
        _pointNum:0,
        _juese:null,
        _cfg:null,
        _bg:null,
        _popup:null,
        _pop_bg:null,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {
        for (let i = 1; i < 21; i++) {
            let point = cc.find("popup/bg/pointRoot/point"+i,this.node)
            this._pointList.push(point)
        }
        this._juese = cc.find("popup/bg/zhizhen",this.node)
        this._juese.opacity = 0
        this._cfg = cc.vv.gameData.getGameCfg()
        this._bg = cc.find("popup/bg",this.node)
        this._popup = cc.find("popup",this.node)
        this._bg.y = cc.winSize.height / 2 + this._bg.height / 2
        this._pop_bg = cc.find("popup/pop_bg",this.node)
        this._pop_bg.on("click",this.onBackGame,this)
        this._pop_bg.getComponent(cc.Button).interactable = false
        this.resetMap(true)
    },

    onDestroy(){

    },

    start () {

    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },

    init(mapInfo){
        this._pointNum = mapInfo.currId
    },

    getIsMapFree(){
        let cfg = cc.vv.gameData.getGameCfg()
        if(!cfg.MapConfig[this._pointNum]){
            return
        }
        let mapInfo = cc.vv.gameData.getMapInfo()
        return cfg.MapConfig[this._pointNum].type === 2 && mapInfo.state === 2
    },

    initNode(){
        for (let i = 0; i < this._pointNum; i++) {
            const element = this._pointList[i];
            if(element.getChildByName("title")){  //房子节点
                for (let j = 0; j < element.children.length; j++) {
                    let child = element.children[j]
                    child.color = this._cfg.normalColor
                }
                element.color = this._cfg.normalColor
            }else{
                cc.find("select",element).active = true
            }
        }
        if(this._pointNum > 0){
            let pointNode = this._pointList[this._pointNum - 1]
            let position = pointNode.convertToWorldSpaceAR(cc.v2(0,0))
            let finalPosition = this._bg.convertToNodeSpaceAR(position)
            this._juese.position = finalPosition
        }
    },

    resetMap(isInit = false){
        for (let i = 0; i < this._pointList.length; i++) {
            const element = this._pointList[i];
            if(element.getChildByName("title")){  //房子节点
                for (let j = 0; j < element.children.length; j++) {
                    let child = element.children[j]
                    child.color = this._cfg.grayColor
                }
                element.color = this._cfg.grayColor
            }else{
                cc.find("select",element).active = false
            }
        }
        this._juese.position = cc.v2(-134.385,-98.021)
        if(!isInit){
            this._pointNum = 0
        }
    },

    show(){
        this._popup.active = true
        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.music_Puss_Click_Show_Map)
        if(this._pointNum === 20){
            this.resetMap()
        }else{
            this.initNode()
        }
        let destY = cc.winSize.height / 2 - 481
        cc.tween(this._bg).to(0.2,{y:destY},{easing:"backOut"}).call(()=>{
            this._pop_bg.getComponent(cc.Button).interactable = true
        }).start()
        this._juese.opacity = 0
        cc.vv.gameData.GetBottomScript().ShowBtnsByState("moveing_1")
    },

    showTip(){
        return new Promise((sucess,failed)=>{
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.music_Puss_Click_Show_Map)
            this._popup.active = true
            this._pop_bg.getComponent(cc.Button).interactable = false
            if(this._pointNum === 20){
                this.resetMap()
            }else{
                this.initNode()
            }
            let destY = cc.winSize.height / 2 - 481
            cc.tween(this._bg).to(0.2,{y:destY},{easing:"backOut"}).call(async ()=>{
                this.jumpToNext()
                await this.awaitTime(3)
                this.hide()
                await this.awaitTime(0.2)
                sucess()
            }).start()
        })
    },

    onBackGame(){
        this._pop_bg.getComponent(cc.Button).interactable = false
        this.hide()
        this.scheduleOnce(()=>{
            cc.vv.gameData.GetBottomScript().ShowBtnsByState("idle")
        },0.2)
    },

    hide(){
        // Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.map_close)
        cc.tween(this._bg).to(0.2,{y:cc.winSize.height + this._bg.height/2},{easing:"backIn"}).call(()=>{
            this._popup.active = false
        }).start()
    },

    jumpToNext(){
        this._pointNum++
        if(this._pointNum > 20){
            this._pointNum = 20
        }
        let pointNode = this._pointList[this._pointNum - 1]
        let position = pointNode.convertToWorldSpaceAR(cc.v2(0,0))
        let finalPosition = this._bg.convertToNodeSpaceAR(position)
        this._juese.opacity = 0
        cc.tween(this._juese).to(0.2,{opacity:255}).to(0.25,{position:finalPosition}).start()
        this.scheduleOnce(()=>{
            let jueseAni = this._juese.getComponent(cc.Animation)
            jueseAni.play("jump")
        },0.2)
        this.scheduleOnce(async ()=>{
            if(pointNode.getChildByName("title")){  //房子节点
                for (let j = 0; j < pointNode.children.length; j++) {
                    let child = pointNode.children[j]
                    child.color = this._cfg.normalColor
                }
                pointNode.color = this._cfg.normalColor
                await this.awaitTime(0.5)
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.music_Puss_Map_YanHua)
                this._juese.opacity = 0
                let yanhua = pointNode.getChildByName("yanhua")
                yanhua.active = true
                let yanhuaAni = yanhua.getComponent(cc.Animation)
                yanhuaAni.play("yanhua")
                yanhuaAni.on("finished",()=>{
                    yanhua.active = false
                    yanhuaAni.off("finished")
                })
            }else{
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.music_Puss_Map_dian)
                cc.find("select",pointNode).active = true
            }
        },0.65)
    },

    // update (dt) {},
});
