    collectJinBi(idxList,progress){
        return new Promise(async (success,failed)=>{
            if(!idxList){
                success()
                return
            }
            if(idxList.length === 0){
                success()
                return
            }
            for (let i = 0; i < idxList.length; i++) {
                const idx = idxList[i]
                let symbol = cc.vv.gameData.GetSlotsScript().GetSymbolByIdx(idx)
                if(symbol){
                    let moveNode = cc.instantiate(cc.vv.gameData.GetPrefabByName("LMSlots_Symbol"))
                    moveNode.parent = this._collectNode
                    cc.find("s13",moveNode).active = true
                    cc.find("coinNum",moveNode).active = false
                    let symbolPos = symbol.node.convertToWorldSpaceAR(cc.v2(0,0))
                    let startPos = this._collectNode.convertToNodeSpaceAR(symbolPos)
                    moveNode.position = startPos
                    let jinbiPos = cc.vv.gameData.getCollectNode().getJinBiWorldPos()
                    let endPos = this._collectNode.convertToNodeSpaceAR(jinbiPos)

                    // 第一个控制点为抛物线右半弧的中点
                    let q1x = startPos.x + (endPos.x - startPos.x) * 0.25;
                    let q1y = startPos.y + (endPos.y - startPos.y) * 0.25;
                    let dir = cc.v2(endPos.x - startPos.x,endPos.y - startPos.y)
                    dir.normalizeSelf()
                    let verticalDir = cc.v2(-dir.y,dir.x)
                    let q1 = cc.v2(q1x + verticalDir.x * 100, q1y + verticalDir.y * 100);
                    // 第二个控制点超出线段的点
                    let q2x = startPos.x + (endPos.x - startPos.x) *0.5;
                    let q2y = startPos.y + (endPos.y - startPos.y) *0.5;
                    let q2 = cc.v2(q2x + verticalDir.x * 100, q2y + verticalDir.y * 100);
                    cc.tween(moveNode).parallel(cc.tween().bezierTo(0.8,q1,q2,endPos,{easing:"quadIn"}),
                        cc.tween().to(0.8,{scale:0.25},{easing:"quadIn"})).call(()=>{
                        moveNode.parent = null
                    }).start()
                    let lizi = cc.instantiate(cc.vv.gameData.GetPrefabByName("tuowei_dian"))
                    lizi.parent = this._collectNode
                    lizi.position = startPos
                    let liziSystem = lizi.getComponent(cc.ParticleSystem)
                    liziSystem.resetSystem()
                    cc.tween(lizi).bezierTo(0.8,q1,q2,endPos,{easing:"quadIn"}).call(()=>{
                        liziSystem.stopSystem()
                        cc.tween(lizi).delay(1).removeSelf().start()
                    }).start()
                }
            }
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.music_Puss_Coins_fly)
            await this.awaitTime(0.8)
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.music_Puss_Coins_Jump_FanKui)
            cc.vv.gameData.getCollectNode().showJinBiCollectEffect()
            cc.vv.gameData.getCollectNode().updateProgress(progress)
            await this.awaitTime(1)
            success()
        })
    },

